def test_apply_code_raises_for_unknown_code():
    cart = Cart([LineItem("apple", Decimal("5.00"))])

    with pytest.raises(UnknownDiscountCode):
        cart.apply_code("MISSING", DiscountRegistry())


@pytest.mark.l4("C-21dee841")
def test_empty_cart_bulk_savings_is_zero():
    """WHEN the cart is empty THEN bulk savings is 0.00."""
    assert Cart().bulk_savings() == Decimal("0.00")


@pytest.mark.l4("C-efd8f9b2")
def test_cart_with_no_qualifying_items_bulk_savings_is_zero():
    """WHEN the cart contains no line items with quantities of at least 10 THEN bulk savings is 0.00."""
    cart = Cart([
        LineItem("apple", Decimal("1.00"), 5),
        LineItem("pear", Decimal("2.00"), 3),
    ])
    assert cart.bulk_savings() == Decimal("0.00")


@pytest.mark.l4("C-cc0190d6")
def test_cart_bulk_savings_sums_qualifying_items():
    """WHEN the cart contains line items with quantities of at least 10 THEN sum individual bulk discounts."""
    cart = Cart([
        LineItem("apple", Decimal("1.00"), 10),  # total=10.00, 5%=0.50
        LineItem("pear", Decimal("2.00"), 15),   # total=30.00, 5%=1.50
    ])
    assert cart.bulk_savings() == Decimal("2.00")


@pytest.mark.l4("C-cc0190d6", "C-efd8f9b2")
def test_cart_bulk_savings_mixed_qualifying_and_non_qualifying():
    """WHEN cart has mixed qualifying and non-qualifying items THEN returns correct sum."""
    cart = Cart([
        LineItem("apple", Decimal("1.00"), 5),   # not qualifying
        LineItem("pear", Decimal("2.00"), 10),   # total=20.00, 5%=1.00
        LineItem("orange", Decimal("1.50"), 3),  # not qualifying
    ])
    assert cart.bulk_savings() == Decimal("1.00")


@pytest.mark.l4("C-ab74596f")
def test_cart_bulk_savings_rounded_to_cents():
    """WHEN calculating total bulk savings THEN return as Decimal rounded to 0.01 using half-up."""
    # Two items each with discount 0.125 -> each rounds to 0.13, sum = 0.26
    cart = Cart([
        LineItem("widget", Decimal("0.25"), 10),  # total=2.50, 5%=0.125->0.13
        LineItem("gadget", Decimal("0.25"), 10),  # total=2.50, 5%=0.125->0.13
    ])
    assert cart.bulk_savings() == Decimal("0.26")

